"""Loopback progress view for the four-cell development pilot."""
from . import live_progress

HTML = '''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>学习率 × 配对数据 · 开发实验进度</title><style>
:root{color-scheme:dark;font-family:system-ui;background:#111b24;color:#e5edf3}body{max-width:1000px;margin:32px auto;padding:0 20px;line-height:1.65}h1{font-size:27px}.muted{color:#9daebc}.row{display:flex;flex-wrap:wrap;gap:14px}.card{background:#1c2a36;border:1px solid #344653;border-radius:14px;padding:18px;margin:12px 0;min-width:0;flex:1}progress{width:100%;height:20px;accent-color:#77dfbc}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px}.value{font-size:25px}a{color:#91e8ce}table{border-collapse:collapse;width:100%;font-size:13px}td,th{text-align:left;padding:9px;border-bottom:1px solid #344653}.table{overflow:auto}#alert{color:#ffba83}.pill{background:#2c4a46;color:#adf0d7;padding:4px 10px;border-radius:20px}</style>
<h1>学习率 × 配对数据</h1><p class="muted">开发筛选实验 · R0 原数据/原学习率 · R1 降学习率 · R2 改配对数据 · R3 两者结合</p>
<p id="alert"></p><div class="row"><section class="card"><span class="muted">当前阶段</span><div class="value" id="stage">连接中</div><span id="status" class="pill"></span></section><section class="card"><span class="muted">本阶段进度</span><div class="value" id="steps">—</div><progress id="bar" max="1" value="0"></progress><div id="detail"></div></section><section class="card"><span class="muted">已用时间</span><div class="value" id="elapsed">—</div><div id="updated" class="muted"></div></section></div>
<p id="message"></p><div class="row"><section class="card"><b>资源 / 当前配置</b><pre id="metrics">尚未加载模型</pre></section><section class="card"><b>数据与复现审计</b><pre id="audit">准备中</pre></section></div>
<section class="card"><b>已完成的开发评测</b><p class="muted">同更新数比较两个因素；可用检查点另按完整能力与误追问门槛筛选。未显示的组别表示尚未评测。</p><div class="table"><table><thead><tr><th>配置 / 更新</th><th>完整正确 C</th><th>缺参正确 Q</th><th>误追问 F</th><th>配对双正确 J</th><th>状态</th></tr></thead><tbody id="checks"></tbody></table></div><div id="result"></div></section>
<p class="muted">每 5 秒刷新 · 仅本机访问 · 本轮不开启新的最终测试</p><script>
const $=x=>document.getElementById(x),names={preparing:'实现与数据准备',audit:'配对数据审计',freeze:'冻结协议',certify:'历史对照复现核验',references:'固定参考评测',training_R1:'R1 训练',training_R2:'R2 训练',training_R3:'R3 训练',development:'检查点评测',selection:'能力门槛筛选',regression:'历史任务回归',reporting:'整理与验证结果',complete:'实验完成'},states={pending:'准备中',running:'运行中',complete:'完成',failed:'失败 / 已停止',stopped:'按规则停止'};
async function refresh(){try{const r=await fetch('/api/state',{cache:'no-store'});if(!r.ok)throw Error(r.status);const s=await r.json();$('stage').textContent=names[s.stage]||s.stage;$('status').textContent=states[s.status]||s.status;$('steps').textContent=s.total_steps?`${s.step||0} / ${s.total_steps}`:'—';$('bar').max=s.total_steps||1;$('bar').value=s.step||0;$('detail').textContent=s.detail||'';$('message').textContent=s.message||'';$('elapsed').textContent=(((s.finished_at||Date.now()/1000)-s.started_at)/60).toFixed(1)+' 分钟';$('updated').textContent=new Date(s.updated_at*1000).toLocaleString();$('alert').textContent=s.stale?'超过 90 秒未收到工作进程心跳，请检查运行状态。':'';$('metrics').textContent=s.metrics?JSON.stringify(s.metrics,null,2):'尚未加载模型';$('audit').textContent=s.audit?JSON.stringify(s.audit,null,2):'准备中';$('checks').replaceChildren();for(const c of s.checkpoints||[]){const tr=document.createElement('tr');for(const k of ['name','C','Q','F','J','status']){const td=document.createElement('td');td.textContent=c[k]??'—';tr.append(td)}$('checks').append(tr)}$('result').replaceChildren();if(s.results_ready){const a=document.createElement('a');a.href='/results';a.textContent='查看结果对比页 →';$('result').append(a)}}catch(e){$('alert').textContent='进度服务暂时无法连接，保留最后显示的数据。'}}refresh();setInterval(refresh,5000);
</script></html>'''

if __name__ == '__main__':
    live_progress.HTML = HTML
    live_progress.main()
